run_wizard() {

# Triển khai bản demo: web Netlify, API Render, DB Neon, ảnh Cloudflare R2 (ADR 0011, docs/deploy.md).
# Chạy từ gốc repo: bash scripts/deploy-demo.sh. Giá trị ghi vào .env.deploy (đã gitignore), chạy lại thì Enter giữ giá trị cũ.
# Tên mục trong dashboard các dịch vụ có thể đổi theo thời gian: nếu không thấy đúng tên, tìm mục tương tự.
ENV_FILE=".env.deploy"
DEFAULT_API_URL="https://atelier-demo-api.onrender.com"

TOTAL_STAGES=12

banner "Triển khai bản demo: Netlify + Render + Neon + R2"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Kiểm tra công cụ và nhánh deploy"
for tool in git node pnpm curl; do
  if command -v "$tool" >/dev/null 2>&1; then step "$tool: có"; else warn "Thiếu $tool: cài rồi chạy lại wizard."; exit 1; fi
done
[[ -f render.yaml && -f web/netlify.toml ]] || { warn "Chạy từ gốc repo (cần render.yaml và web/netlify.toml)."; exit 1; }
say "Netlify và Render deploy từ nhánh main của GitHub."
say "render.yaml và web/netlify.toml phải đã có trên main (merge PR #2 trước)."
if git ls-remote --exit-code origin main >/dev/null 2>&1 && git show origin/main:render.yaml >/dev/null 2>&1; then
  step "origin/main đã có render.yaml."
else
  warn "origin/main chưa có render.yaml: merge PR #2 rồi chạy lại (hoặc chọn nhánh khác trong hai dashboard)."
  confirm "Vẫn tiếp tục?" || exit 1
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Neon: database Postgres"
say "Tạo một project Neon gói Free, đặt ở Singapore cho gần khách Việt Nam."
open_url "https://console.neon.tech/app/projects"
step "New Project → đặt tên (ví dụ atelier-demo) → Region: AWS Asia Pacific (Singapore) → Create."
step "Bấm Connect. TẮT 'Connection pooling' (pg-boss cần LISTEN/NOTIFY, pooler không hỗ trợ)."
step "Chép connection string: host KHÔNG có '-pooler', cuối có '?sslmode=require'."
ask_secret DATABASE_URL "Dán connection string direct:"
if [[ "$DATABASE_URL" == *-pooler* ]]; then
  warn "Chuỗi này có '-pooler': hãy tắt Connection pooling rồi chép lại."
  ask_secret DATABASE_URL "Dán connection string direct:"
fi
write_env DATABASE_URL "$DATABASE_URL"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: tạo hai bucket"
say "R2 lưu ảnh sản phẩm (bucket công khai) và chứng từ (bucket riêng)."
note "Lần đầu bật R2, Cloudflare có thể đòi thêm phương thức thanh toán; gói Free không tính tiền trong hạn mức."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "Create bucket → tên 'atelier-demo-public' → Create."
step "Create bucket → tên 'atelier-demo-private' → Create."
ask R2_PUBLIC_BUCKET "Tên bucket công khai (Enter nếu đúng như trên, hoặc gõ tên):"
[[ -n "$R2_PUBLIC_BUCKET" ]] || R2_PUBLIC_BUCKET="atelier-demo-public"
ask R2_PRIVATE_BUCKET "Tên bucket riêng:"
[[ -n "$R2_PRIVATE_BUCKET" ]] || R2_PRIVATE_BUCKET="atelier-demo-private"
write_env R2_PUBLIC_BUCKET "$R2_PUBLIC_BUCKET"
write_env R2_PRIVATE_BUCKET "$R2_PRIVATE_BUCKET"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: URL công khai cho ảnh"
say "Ảnh trên website tải thẳng từ bucket công khai qua địa chỉ r2.dev (chưa cần tên miền)."
step "Mở bucket '$R2_PUBLIC_BUCKET' → Settings → Public Development URL (hay 'R2.dev subdomain') → Enable/Allow."
step "Chép URL dạng https://pub-xxxxxxxx.r2.dev (không có dấu / ở cuối)."
note "KHÔNG bật public cho bucket '$R2_PRIVATE_BUCKET': chứng từ đi qua link ký tạm của API."
ask MEDIA_PUBLIC_URL "Dán URL công khai của bucket ảnh:"
write_env MEDIA_PUBLIC_URL "${MEDIA_PUBLIC_URL%/}"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: API token cho API"
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "Create API token (Account hay User token) → Permissions: Object Read & Write."
step "Phạm vi: chỉ hai bucket '$R2_PUBLIC_BUCKET' và '$R2_PRIVATE_BUCKET' → Create."
step "Trang kết quả hiện Access Key ID, Secret Access Key và endpoint S3 (https://<account_id>.r2.cloudflarestorage.com)."
warn "Secret Access Key chỉ hiện một lần: chép ngay."
ask R2_ENDPOINT "Dán endpoint S3:"
ask_secret R2_ACCESS_KEY_ID "Dán Access Key ID:"
ask_secret R2_SECRET_ACCESS_KEY "Dán Secret Access Key:"
write_env R2_ENDPOINT "${R2_ENDPOINT%/}"
write_env R2_ACCESS_KEY_ID "$R2_ACCESS_KEY_ID"
write_env R2_SECRET_ACCESS_KEY "$R2_SECRET_ACCESS_KEY"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Netlify: tạo site cho web"
say "Tạo site trước để có URL *.netlify.app; API (bước sau) cần URL này."
open_url "https://app.netlify.com/start"
step "Import an existing project → GitHub → chọn repo 'ecommerce' → Branch to deploy: main."
step "Monorepo: chọn package 'web' (Package directory = web). Base directory để TRỐNG."
note "Lệnh build và proxy /api lấy từ web/netlify.toml; không cần sửa các ô build."
step "Deploy. Lần đầu web chưa gọi được API, không sao."
step "Chép URL site dạng https://<tên>.netlify.app (Site configuration → Change site name nếu muốn đổi tên)."
ask SITE_URL "Dán URL site Netlify:"
write_env SITE_URL "${SITE_URL%/}"
SITE_URL="${SITE_URL%/}"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Render: API từ Blueprint"
VNPAY_TMN_CODE=$(grep -E '^VNPAY_TMN_CODE=' .env 2>/dev/null | cut -d= -f2- || true)
VNPAY_HASH_SECRET=$(grep -E '^VNPAY_HASH_SECRET=' .env 2>/dev/null | cut -d= -f2- || true)
if [[ -n "$VNPAY_TMN_CODE" && -n "$VNPAY_HASH_SECRET" ]]; then
  write_env VNPAY_TMN_CODE "$VNPAY_TMN_CODE"
  write_env VNPAY_HASH_SECRET "$VNPAY_HASH_SECRET"
else
  ask VNPAY_TMN_CODE "vnp_TmnCode (sandbox VNPAY):"
  ask_secret VNPAY_HASH_SECRET "vnp_HashSecret (sandbox VNPAY):"
  write_env VNPAY_TMN_CODE "$VNPAY_TMN_CODE"
  write_env VNPAY_HASH_SECRET "$VNPAY_HASH_SECRET"
fi
open_url "https://dashboard.render.com/select-repo?type=blueprint"
step "New → Blueprint → chọn repo 'ecommerce', branch main. Render đọc render.yaml (service atelier-demo-api, gói Free)."
step "Điền các biến Render hỏi. Lấy giá trị trong file $ENV_FILE (mở bằng editor, không commit):"
say "    DATABASE_URL, SITE_URL, R2_ENDPOINT, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY,"
