step "Apply. Chờ build và deploy xanh (lần đầu vài phút; log có 'API đang chạy' và payments VnpayPaymentGateway)."
step "Chép URL service dạng https://atelier-demo-api.onrender.com (có thể có hậu tố nếu tên đã bị dùng)."
ask API_URL "Dán URL API trên Render:"
API_URL="${API_URL%/}"
write_env API_URL "$API_URL"
if curl -fsS --max-time 90 "$API_URL/healthz" >/dev/null 2>&1; then step "API trả lời /healthz."; else warn "Chưa gọi được $API_URL/healthz: xem log trên Render rồi chạy lại wizard."; fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Netlify: nối web với API"
if [[ "$API_URL" != "$DEFAULT_API_URL" ]]; then
  warn "URL Render khác $DEFAULT_API_URL: phải sửa proxy trong web/netlify.toml."
