say "    NUXT_PUBLIC_SITE_URL = $SITE_URL"
step "Deploys → Trigger deploy → Deploy site (để nhận biến mới)."
pause
if curl -fsS --max-time 60 "$SITE_URL/api/brands" >/dev/null 2>&1; then step "Proxy /api qua Netlify chạy."; else warn "$SITE_URL/api/brands chưa trả lời: chờ deploy xong rồi thử lại."; fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Tạo chủ shop trên database Neon"
